def judgePoint24(cards: list[int]) -> bool:
    EPS = 1e-6
    def dfs(nums):
        if len(nums) == 1:
            return abs(nums[0] - 24) < EPS
        for i in range(len(nums)):
            for j in range(len(nums)):
                if i != j:
                    next_nums = [nums[k] for k in range(len(nums)) if k != i and k != j]
                    a, b = nums[i], nums[j]
                    for res in [a + b, a - b, b - a, a * b]:
                        if dfs(next_nums + [res]): return True
                    if abs(b) > EPS and dfs(next_nums + [a / b]): return True
                    if abs(a) > EPS and dfs(next_nums + [b / a]): return True
        return False
    return dfs([float(c) for c in cards])

